#!/usr/bin/env python3
"""Turn 35 Wave 78: THE BREAKTHROUGH LADDER AND THE SPECIAL-COACH LOOK-AHEAD - the percentages
that close one of the corpus's eight surviving gaps, the coach category pools, and a mechanic
that lets you control the RNG without spending the expensive coach.

Wave 78's two centrepieces:

1. THE BREAKTHROUGH LADDER IS NOW KNOWN: Common 5% / Rare 10% / Legendary 20%,
   corroborated by three sources spanning DLS20 to DLS24. The Legendary 20% figure
   is new - the corpus only had the 5% and 10%.

2. THE LOOK-AHEAD TRICK: a Legendary Special coach reveals the next FOUR upgradable
   stats and can be cancelled WITHOUT being consumed. That converts the most
   expensive item in the game into a free information tool, worth about 420 gems per
   special player.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w78')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_bt=new_ev("LevelWinner DLS20 Training Guide (3 Jul 2020, the full breakthrough ladder and effect sizes), r/DreamLeagueSoccer 1b8eain (6 Mar 2024, the 20% Legendary breakthrough chance and the Commercial breakeven), szi4dx (23 Feb 2022, '10% more chance of breakthrough'), 1u69y7v (15 Jun 2026, the special-coach look-ahead trick), 1pp07c2 (17 Dec 2025, the 6-7 special coaches and the 420-gem saving), 1pudgh8 (24 Dec 2025, the coach category pools and the +10/+11 cap), 1ckf0xo (5 May 2024, the coach gem prices and the 45-gem saving), 1en4rl1 (8 Aug 2024, the gem prices at a maxed facility and the per-player coach counts), 1qbkdkl (13 Jan 2026, the maxed-facility prices and the scouted player prices), 1r5jpmv (15 Feb 2026, rare goalkeepers yield only one Common coach), 1bxmcwf (6 Apr 2024, the captain re-roll and the 1,500-coin/75-gem starter grant), 1lieh2g (23 Jun 2025, the 1% agent odds and the recovery-tab lever), 1g1vdt0 (12 Oct 2024, the Training facility paying for itself after ~20 Legendary coaches), 191fwzb (8 Jan 2024, the 9.25 Rare coaches per player figure), 1b4ovuj (2 Mar 2024, the 20 Rare coaches per player figure), 1q45hs3 (4 Jan 2026, the GK training observation), gamedls.net (30 Aug 2025, the random player and attribute targeting)",
    "THE BREAKTHROUGH LADDER, THE COACH CATEGORY POOLS, THE LOOK-AHEAD TRICK, AND THE COACH PRICE LADDER. (1) THE BREAKTHROUGH LADDER, which closes one of the corpus's eight surviving gaps: **Common 5% · Rare 10% · Legendary 20%** - from LevelWinner's DLS20 guide, which also gives the effect sizes ('Common... improve two random stats by two points each for one player, with a 5 percent Breakout Rating... Rare... increasing three random stats by three points each, with a 10 percent Breakout Rating... Legendary Coaches... provide a four-point increase for all four stats covered... with a 20 percent Breakout Rating'). The 5% and 10% figures were already in the corpus as a DLS20 baseline; **the Legendary 20% is new, and it is corroborated twice more** - '1000 gems gives you 6 legendary coaches, (a.k.a 6x9=54 single point upgrades, with 20% breakthrough chance)' (March 2024) and 'Legendary coaches... Also 10% more chance of breakthrough' (February 2022, i.e. 20% against Rare's 10%). So the ladder is three-source across DLS20-DLS24 and very likely holds in DLS26. (2) THE COACH CATEGORY POOLS, the definitive mapping: 'There are 2 types of coaches for outfield players, Fitness and Tech. **Fitness stats are SPE, ACC, STA and STR. While Tech stats are CON, PAS, SHO and TAC.** These become the pool for the RNG to decide what to upgrade.' This maps the coaching system exactly onto the official stat model, and it is why the corpus's chain-by-category method works. (3) THE LOOK-AHEAD TRICK, the wave's most valuable mechanic: 'You want to always keep at least 1 Legendary Special coach because it will allow you to **look at the next 4 upgradable stats** (you can cancel it and use any other coach without losing the legendary special coach). Always use a common coach if at least 1 of the stats isn't what you want.' Confirmed by a second commenter: 'You never lose the coach no matter what, whether you close the app or simply click on the \"x\" to cancel the coaching... If your next 2 upgradable stats are not what you want, you use a common coach (ALWAYS).' So the most expensive item in the game doubles as a **free information tool**, and the saving is quantified: 'it takes 6-7 Legendary Special Coaches to max a special player, that would mean you would be saving about 70 gems x 6 or x 7 for every maxed Special Player, which equates to 420 gems for every maxed special player.' (4) THE COACH GEM PRICE LADDER, with the maxed-facility discount quantified: **Common 17 gems · Rare 52 (maxed) / 67 (unmaxed) · Legendary 157 (maxed) / 202 (unmaxed)**. So the Training facility saves **15 gems per Rare and 45 per Legendary** - 'You lose 45 gem each time you use legendary coach now' describes the same delta from the other side. (5) THE TRAINING FACILITY PAYS FOR ITSELF AFTER ~20 LEGENDARY COACHES - a THIRD independent source for this figure ('Max your training facility, never use gems on coaches until you have a maxed training facility. It's a long term investment and will pay itself after 20 or so legendary coaches due to the saved gems'). (6) THE COMMERCIAL-vs-COACHES BREAKEVEN, a genuine decision rule: '1 common coach price is generally around 200g if bought efficiently. 200x54 = 10800. To get 10800 with the commercial upgrades (10%) you need to get around 108,000 coins. This means that if you never, ever grind enough past 108k then keep your diamonds for upgrades... But if you're more a perfectionist who wants every player to be redone to their best possible stats... then DEFINITELY max your commercial.' (7) RARE GOALKEEPERS YIELD ONLY ONE COMMON COACH: 'Don't buy rare goalies as they also only get 1 common coach after release, same as any common goalie' - a specific exception to the release mapping, and a direct instruction for coach farming. (8) THE CAPTAIN SELECTION IS RE-ROLLABLE: 'if you are maxing a low rated legendary card that is between the ratings of 80-82, you can find them in the captain selection when you start the game. If you don't get the specific card you can just delete the game until you get it. Once you do that you will get 1,500 coins and 75 gems' - which is a THIRD source for the 1,500c/75g starter grant, against the 1,200c/40g outlier. (9) THE RECOVERY-TAB GACHA LEVER, with its odds: 'legendary agents have a 1% chance thats it... there is 12 of the new champions cards coming out so the odds of you getting one are about 12 out of 120/130 which gives you roughly a 10% chance... You can increase this by buying more legendary players and selling them during the event so that they remain in the recover players section and not in the transfer window.' (10) SCOUTED PRICES: 'you can get legendaries for as little as 1400 gold. And common players for ~60 gold' - the concrete value of a maxed scout. (11) MAX RATING = base + 10, 'but in some very rare cases it could go upto +11.' (12) CONFLICT on Rare coaches per player: most sources say ~20 (and '18-22 overall'), one says 9.25 (148 for a 16-player team). The 90-point model implies 15. (13) GK TRAINING can produce badly unbalanced keepers even with Common coaches - 'i trained courtois and he got like 97 gkh and just 85 gkr' - which is the practical reason for the GKR>GKH rule.",
    "evidence/raw/turn35_w78/EV-491_breakthrough_ladder_and_lookahead.html",
    "BREAKTHROUGH LADDER (closes a surviving gap): Common 5% · Rare 10% · LEGENDARY 20% - three sources across DLS20-DLS24, with the 20% figure new to the corpus. COACH CATEGORY POOLS: Fitness = SPE, ACC, STA, STR · Technical = CON, PAS, SHO, TAC - the coaching system mapped onto the official stat model. LOOK-AHEAD TRICK: a Legendary Special coach reveals the next FOUR upgradable stats and can be cancelled WITHOUT being consumed, so the most expensive item in the game is a free information tool worth ~420 gems per special player. COACH PRICES: Common 17g · Rare 52g maxed / 67g unmaxed · Legendary 157g maxed / 202g unmaxed - so Training saves 15g per Rare and 45g per Legendary. TRAINING PAYS FOR ITSELF after ~20 Legendary coaches (third source). COMMERCIAL BREAKEVEN: max Commercial if you will grind past ~108,000 coins, else keep gems for facilities. RARE GOALKEEPERS yield only ONE Common coach on release. THE CAPTAIN SELECTION IS RE-ROLLABLE by deleting the game, and the starter grant is 1,500 coins + 75 gems (third source). RECOVERY-TAB LEVER: legendary agents are ~1% per card, ~10-15% for a Champion, and buying/releasing during an event keeps cards in Recovery and out of the transfer window. Scouted prices: legendaries ~1,400, commons ~60. Max rating = base + 10, rarely +11. CONFLICT: Rare coaches per player is ~20 (most sources) vs 9.25 (one). GKs can end badly unbalanced even with Common coaches (97 GKH vs 85 GKR)",
    quality="community")

add_claim("THE BREAKTHROUGH LADDER: Common 5% · Rare 10% · Legendary 20%. The 5% and 10% were already recorded as a DLS20 baseline; **the Legendary 20% is new**, and the whole ladder is corroborated by three sources spanning DLS20 to DLS24.", 2, "coaching/breakthrough-ladder", [e_bt], notes="CLOSES one of the eight surviving gaps")
add_claim("A second source for the 20% Legendary breakthrough chance: '1000 gems gives you 6 legendary coaches, (a.k.a 6x9=54 single point upgrades, with 20% breakthrough chance)' - and a third puts it as 'Legendary coaches... 10% more chance of breakthrough' than Rare.", 2, "coaching/legendary-20-percent-breakthrough", [e_bt])
add_claim("THE COACH CATEGORY POOLS: **Fitness coaches draw from SPE, ACC, STA and STR** · **Technical coaches draw from CON, PAS, SHO and TAC**. This maps the coaching system exactly onto the official stat model and is why chaining by category works.", 2, "coaching/category-pools", [e_bt])
add_claim("THE LOOK-AHEAD TRICK: a Legendary Special coach reveals the next FOUR upgradable stats and can be cancelled WITHOUT being consumed - 'you can cancel it and use any other coach without losing the legendary special coach.' Always use a Common coach if at least one previewed stat is wrong.", 2, "coaching/look-ahead-trick", [e_bt], notes="The most expensive item in the game doubles as a free information tool")
add_claim("The look-ahead trick is worth about 420 gems per special player: 'it takes 6-7 Legendary Special Coaches to max a special player, that would mean you would be saving about 70 gems x 6 or x 7 for every maxed Special Player, which equates to 420 gems.'", 2, "coaching/look-ahead-value-420-gems", [e_bt])
add_claim("THE COACH GEM PRICE LADDER: Common 17 gems · Rare 52 (maxed facility) / 67 (unmaxed) · Legendary 157 (maxed) / 202 (unmaxed). So the Training facility saves **15 gems per Rare and 45 per Legendary**.", 2, "coaching/gem-price-ladder", [e_bt])
add_claim("THE TRAINING FACILITY PAYS FOR ITSELF AFTER ~20 LEGENDARY COACHES - a third independent source: 'Max your training facility, never use gems on coaches until you have a maxed training facility. It's a long term investment and will pay itself after 20 or so legendary coaches due to the saved gems.'", 2, "facilities/training-pays-back-after-20-third-source", [e_bt])
add_claim("THE COMMERCIAL-vs-COACHES BREAKEVEN: a Common coach bought efficiently costs ~200 gems for 54 upgrade points = 10,800, which at a 10% Commercial bonus needs ~108,000 coins to match. **So max Commercial only if you will grind past ~108,000 coins; otherwise keep gems for facilities.**", 3, "economy/commercial-breakeven-108k-coins", [e_bt])
add_claim("RARE GOALKEEPERS YIELD ONLY ONE COMMON COACH on release - 'Don't buy rare goalies as they also only get 1 common coach after release, same as any common goalie.' A specific exception to the release mapping, and a direct instruction for coach farming.", 3, "coaching/rare-goalkeepers-one-common-coach", [e_bt])
add_claim("THE CAPTAIN SELECTION IS RE-ROLLABLE: 'you can find them in the captain selection when you start the game. If you don't get the specific card you can just delete the game until you get it.' This is also a THIRD source for the 1,500 coins + 75 gems starter grant, against the 1,200c/40g outlier.", 3, "economy/captain-selection-reroll", [e_bt])
add_claim("Legendary agents have about a 1% chance per card, and with 12 Champion cards in a pool of 120-130 that is 'roughly a 10% chance' of pulling one. The recovery-tab lever improves it: 'buying more legendary players and selling them during the event so that they remain in the recover players section and not in the transfer window.'", 3, "economy/agent-odds-and-recovery-lever", [e_bt])
add_claim("SCOUTED PRICES at a high scout level: 'you can get legendaries for as little as 1400 gold. And common players for ~60 gold' - the concrete value of the scout discount ladder.", 3, "transfers/scouted-prices", [e_bt])
add_claim("A card's max rating is the +10 of its base overall, 'but in some very rare cases it could go upto +11.'", 2, "coaching/max-rating-plus-10-rarely-11", [e_bt])
add_claim("CONFLICT - Rare coaches per player: most sources say about 20 ('18-22 overall'), one says 9.25 ('148 rare coaches to max a 16 player team'). The 90-point model implies 15. Unresolved; the spread is position-dependent.", 3, "coaching/rare-coaches-per-player-conflict", [e_bt])
add_claim("Goalkeepers can end badly unbalanced even with Common coaches - 'i trained courtois and he got like 97 gkh and just 85 gkr but my donnarumma was more balanced with 94 gkr and 91 gkh both common coaches' - which is the practical reason for the GKR > GKH rule.", 3, "coaching/gk-unbalance-observed", [e_bt])
add_claim("When a coach is applied the system randomly determines WHICH player in the squad receives the upgrade, then randomly determines the attribute - so squad composition is itself a coaching variable.", 2, "coaching/random-player-targeting", [e_bt], notes="Corroborated by a second source; interacts with the one-player-at-a-time method")

for name in ('EV-491_breakthrough_ladder_and_lookahead.html',):
    p=os.path.join(RAW_DIR,name)
    if not os.path.exists(p):
        with open(p,'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
